@spec wm_splice_spec  src=tests/specs/wm_splice_spec.lua  loc=121  cases=6
@exercises wiringManager (wm)
@surface   wm:mutate, wm:graph, wm:spliceIntoEdge, wm:spliceable
@harness   mk

# Intent
  (none)

# Helpers
  @fn mkWm(harness, opts)  @ 4-9
  @fn seedSource(wm, id)  @ 12-17
      -- Source node seeded directly (no REAPER track): splice never touches a track.
  @fn fxNode(ins, outs)  @ 19-22
  @fn seedWireAndNode(wm)  @ 25-36
      -- s --0.5--> f, with a free 1x1 fx node `n` off to the side.

# Cases
  @case 'spliceIntoEdge re-points the wire through the node and snaps its pos'  [harness]  @ 40-60
  @case 'the wire gain rides the input side; the output leg is unity'  [harness]  @ 63-72
  @case 'spliceable refuses a node with no free audio pair 1'  [harness]  @ 75-84
  @case 'spliceable refuses a node without both an audio in and an out pair'  [harness]  @ 87-94
  @case 'spliceable refuses an end of the wire and a splice that would close a loop'  [harness]  @ 97-107
  @case 'spliceIntoEdge refuses what spliceable refuses, leaving the graph alone'  [harness]  @ 110-119

# Uses (outbound edges)
  @use call wm:mutate  @ 13,27,80,91,102
  @use call wm:graph  @ 33,45,68,114,118
  @use call wm:spliceIntoEdge  @ 44,67,115
  @use call wm:spliceable  @ 79,83,92,93,101,106

